module.exports = {
  preset: 'ts-jest',
  testEnvironment: 'node',
  testMatch: ['**/tests/**/*.test.ts'],
  collectCoverageFrom: ['src/**/*.ts'],
  moduleNameMapper: {
    '^uuid$': 'uuid'
  },
  transform: {
    '^.+\\.tsx?$': ['ts-jest', {
      useESM: true,
    }],
  },
};

import express from "express";
import { Router } from "express";
import cors from "cors";
import dotenv from "dotenv";
import * as Sentry from "@sentry/node";
import authRoutes from "./routes/authRoutes";
import financeRoutes from "./routes/financeRoutes";
import savingsRoutes from "./routes/savingsRoutes";
import userRoutes from "./routes/userRoutes";
import { errorHandler, notFoundHandler } from "./middleware/errorHandler";
import { logger, requestIdMiddleware } from "./utils/logger";
import { metricsMiddleware, getMetrics } from "./utils/metrics";
import { config } from "./config/env";
import { optionalAuthMiddleware } from "./middleware/optionalAuthMiddleware";
import { getBenchmark } from "./controllers/financeController";
import { compressionMiddleware } from "./middleware/compression";
import { performanceMiddleware, getPerformanceMetrics } from "./middleware/performance";
import { cacheService } from "./config/cache";
import insightsRoutes from "./routes/insightsRoutes";

dotenv.config();

// Initialize Sentry
if (config.sentryDsn) {
  Sentry.init({
    dsn: config.sentryDsn,
    environment: process.env.NODE_ENV || 'development',
    tracesSampleRate: 1.0,
  });
}

const app = express();
const PORT = process.env.PORT || 3001;

// ----------------------------------
// ⭐ CORS Configuration
// ----------------------------------
// ⭐ CORS Configuration
// ----------------------------------
const allowedOrigins = [
  "http://localhost:3000",
  "http://localhost:3001",
  "http://127.0.0.1:3000",
  "http://127.0.0.1:3001",
  "https://capstack-2k25-frontend.onrender.com",
  "https://capstack-2k25.onrender.com",
  // Add environment variable support for custom deployment URLs
  process.env.FRONTEND_URL || "",
];

app.use(
  cors({
    origin: function (origin, callback) {
      // Allow requests with no origin (mobile apps, curl, Postman)
      if (!origin) return callback(null, true);

      if (allowedOrigins.includes(origin) || allowedOrigins.includes(origin?.replace(/\/$/, ""))) {
        callback(null, true);
      } else {
        // In development, be lenient
        if (process.env.NODE_ENV === 'development') {
          logger.warn(`CORS: Allowing origin in development mode: ${origin}`);
          return callback(null, true);
        }
        logger.warn(`CORS rejected origin: ${origin}`);
        callback(new Error("Not allowed by CORS"));
      }
    },
    credentials: true,
    methods: ["GET", "POST", "PUT", "DELETE", "OPTIONS", "PATCH"],
    allowedHeaders: ["Content-Type", "Authorization", "X-Requested-With"],
    optionsSuccessStatus: 200,
    maxAge: 86400, // 24 hours
  })
);

// Allow preflight
app.options("*", cors());

// ----------------------------------
// Performance Middleware
// ----------------------------------
// Compression should be early in the middleware chain
app.use(compressionMiddleware);

// Performance monitoring
app.use(performanceMiddleware);

// ----------------------------------
// Middleware
// ----------------------------------

app.use(express.json({ limit: "10mb" }));
app.use(express.urlencoded({ limit: "10mb", extended: true }));

// Request ID middleware
app.use(requestIdMiddleware);

// Metrics middleware
app.use(metricsMiddleware);

// Request logging middleware
app.use((req: any, res: any, next: any) => {
  logger.info(`${req.method} ${req.originalUrl}`, req.requestId);
  next();
});

// ----------------------------------
// Health Check
// ----------------------------------
app.get("/health", (req, res) => {
  res.json({
    status: "ok",
    message: "Backend API running successfully",
    timestamp: new Date().toISOString(),
    version: process.env.API_VERSION || "1.0.0",
  });
});

// Metrics endpoint
app.get("/metrics", async (req, res) => {
  try {
    const metrics = await getMetrics();
    res.set('Content-Type', 'text/plain; charset=utf-8');
    res.send(metrics);
  } catch (error) {
    res.status(500).send('Error generating metrics');
  }
});

// ----------------------------------
// Routes
// ----------------------------------
app.use("/auth", authRoutes);
app.use("/finance", financeRoutes);
app.use("/savings", savingsRoutes);
app.use("/user", userRoutes);
app.use("/api/insights", insightsRoutes);

// ----------------------------------
// API Aliases (compat with frontend paths)
// ----------------------------------
const apiRouter = Router();
// Alias: /api/benchmarking -> /finance/benchmark
apiRouter.get("/benchmarking", optionalAuthMiddleware, getBenchmark);
app.use("/api", apiRouter);

// Root endpoint
app.get("/", (req, res) => {
  res.json({
    message: "CAPSTACK Backend API",
    version: "1.0.0",
    status: "running",
    endpoints: {
      health: "/health",
      auth: "/auth",
      finance: "/finance",
      savings: "/savings",
      user: "/user",
      metrics: "/api/metrics/performance",
    },
  });
});

// Performance metrics endpoint
app.get("/api/metrics/performance", getPerformanceMetrics);

// ----------------------------------
// Error Handling
// ----------------------------------
// 404 handler - must be after all other routes
app.use(notFoundHandler);

// Error handler - must be last
app.use(errorHandler);

// Sentry error handler - must be after all other error handlers
if (config.sentryDsn) {
  Sentry.setupExpressErrorHandler(app);
}

// ----------------------------------
// Server Startup
// ----------------------------------
// Initialize cache connection
(async () => {
  try {
    if (process.env.REDIS_ENABLED !== 'false') {
      await cacheService.connect();
      logger.info('✅ Redis cache connected');
    } else {
      logger.info('ℹ️  Redis cache disabled');
    }
  } catch (error) {
    logger.warn('⚠️  Redis connection failed, running without cache');
    logger.warn(`Redis error: ${error}`);
  }
})();

const server = app.listen(PORT, () => {
  logger.info(`✅ Server running on port ${PORT}`);
  logger.info(`📍 Environment: ${process.env.NODE_ENV || 'development'}`);
  logger.info(`🌍 Allowed origins: ${allowedOrigins.join(', ')}`);
  logger.info(`⚡ Performance monitoring enabled`);
  logger.info(`🗜️  Response compression enabled`);
});

// Graceful shutdown
process.on("SIGTERM", () => {
  logger.warn("SIGTERM received, shutting down gracefully");
  server.close(async () => {
    // Disconnect from Redis
    try {
      await cacheService.disconnect();
      logger.info("Redis disconnected");
    } catch (error) {
      logger.warn("Error disconnecting Redis");
    }
    logger.info("Server shut down");
    process.exit(0);
  });
});

process.on("SIGINT", () => {
  logger.warn("SIGINT received, shutting down gracefully");
  server.close(async () => {
    // Disconnect from Redis
    try {
      await cacheService.disconnect();
      logger.info("Redis disconnected");
    } catch (error) {
      logger.warn("Error disconnecting Redis");
    }
    logger.info("Server shut down");
    process.exit(0);
  });
});

// Unhandled promise rejection
process.on("unhandledRejection", (reason, promise) => {
  logger.error({
    message: "Unhandled Rejection",
    reason,
    promise,
  });
});

export default app;

import { createClient, RedisClientType } from 'redis';

interface CacheConfig {
  host: string;
  port: number;
  password?: string;
  db?: number;
  ttl: {
    default: number;
    session: number;
    healthScore: number;
    transactions: number;
    analytics: number;
    mlPredictions: number;
  };
}

class CacheService {
  private client: RedisClientType | null = null;
  private config: CacheConfig;
  private isConnected: boolean = false;

  constructor() {
    this.config = {
      host: process.env.REDIS_HOST || 'localhost',
      port: parseInt(process.env.REDIS_PORT || '6379'),
      password: process.env.REDIS_PASSWORD,
      db: parseInt(process.env.REDIS_DB || '0'),
      ttl: {
        default: 300, // 5 minutes
        session: 900, // 15 minutes
        healthScore: 300, // 5 minutes
        transactions: 120, // 2 minutes
        analytics: 600, // 10 minutes
        mlPredictions: 1800, // 30 minutes
      },
    };
  }

  async connect(): Promise<void> {
    if (this.isConnected) {
      return;
    }

    try {
      this.client = createClient({
        socket: {
          host: this.config.host,
          port: this.config.port,
        },
        password: this.config.password,
        database: this.config.db,
      });

      this.client.on('error', (err: any) => {
        console.error('Redis Client Error:', err);
      });

      this.client.on('connect', () => {
        console.log('Redis Client Connected');
        this.isConnected = true;
      });

      this.client.on('disconnect', () => {
        console.log('Redis Client Disconnected');
        this.isConnected = false;
      });

      await this.client.connect();
    } catch (error) {
      console.error('Failed to connect to Redis:', error);
      // Gracefully handle Redis connection failure - app should work without cache
      this.client = null;
      this.isConnected = false;
    }
  }

  async disconnect(): Promise<void> {
    if (this.client && this.isConnected) {
      await this.client.quit();
      this.isConnected = false;
    }
  }

  private getCacheKey(prefix: string, key: string): string {
    return `capstack:${prefix}:${key}`;
  }

  async get<T>(prefix: string, key: string): Promise<T | null> {
    if (!this.client || !this.isConnected) {
      return null;
    }

    try {
      const cacheKey = this.getCacheKey(prefix, key);
      const value = await this.client.get(cacheKey);

      if (!value) {
        return null;
      }

      return JSON.parse(value) as T;
    } catch (error) {
      console.error('Cache get error:', error);
      return null;
    }
  }

  async set(prefix: string, key: string, value: any, ttl?: number): Promise<boolean> {
    if (!this.client || !this.isConnected) {
      return false;
    }

    try {
      const cacheKey = this.getCacheKey(prefix, key);
      const serializedValue = JSON.stringify(value);
      const cacheTTL = ttl || this.config.ttl.default;

      await this.client.setEx(cacheKey, cacheTTL, serializedValue);
      return true;
    } catch (error) {
      console.error('Cache set error:', error);
      return false;
    }
  }

  async delete(prefix: string, key: string): Promise<boolean> {
    if (!this.client || !this.isConnected) {
      return false;
    }

    try {
      const cacheKey = this.getCacheKey(prefix, key);
      await this.client.del(cacheKey);
      return true;
    } catch (error) {
      console.error('Cache delete error:', error);
      return false;
    }
  }

  async deletePattern(pattern: string): Promise<boolean> {
    if (!this.client || !this.isConnected) {
      return false;
    }

    try {
      const keys = await this.client.keys(`capstack:${pattern}`);
      if (keys.length > 0) {
        await this.client.del(keys);
      }
      return true;
    } catch (error) {
      console.error('Cache delete pattern error:', error);
      return false;
    }
  }

  async invalidateUser(userId: number): Promise<void> {
    // Invalidate all user-related caches
    await this.deletePattern(`user:${userId}:*`);
    await this.deletePattern(`healthScore:${userId}:*`);
    await this.deletePattern(`transactions:${userId}:*`);
    await this.deletePattern(`analytics:${userId}:*`);
  }

  async getOrSet<T>(
    prefix: string,
    key: string,
    fetchFunction: () => Promise<T>,
    ttl?: number
  ): Promise<T> {
    // Try to get from cache first
    const cachedValue = await this.get<T>(prefix, key);

    if (cachedValue !== null) {
      return cachedValue;
    }

    // If not in cache, fetch and store
    const value = await fetchFunction();
    await this.set(prefix, key, value, ttl);

    return value;
  }

  async exists(prefix: string, key: string): Promise<boolean> {
    if (!this.client || !this.isConnected) {
      return false;
    }

    try {
      const cacheKey = this.getCacheKey(prefix, key);
      const result = await this.client.exists(cacheKey);
      return result === 1;
    } catch (error) {
      console.error('Cache exists error:', error);
      return false;
    }
  }

  async increment(prefix: string, key: string, amount: number = 1): Promise<number> {
    if (!this.client || !this.isConnected) {
      return 0;
    }

    try {
      const cacheKey = this.getCacheKey(prefix, key);
      return await this.client.incrBy(cacheKey, amount);
    } catch (error) {
      console.error('Cache increment error:', error);
      return 0;
    }
  }

  async getStats(): Promise<any> {
    if (!this.client || !this.isConnected) {
      return { connected: false };
    }

    try {
      const info = await this.client.info('stats');
      return {
        connected: this.isConnected,
        info,
      };
    } catch (error) {
      console.error('Cache stats error:', error);
      return { connected: false, error };
    }
  }

  getTTL(type: keyof CacheConfig['ttl']): number {
    return this.config.ttl[type];
  }
}

// Export singleton instance
export const cacheService = new CacheService();

// Helper functions for specific cache types
export const userCache = {
  get: (userId: number) => cacheService.get('user', userId.toString()),
  set: (userId: number, data: any) =>
    cacheService.set('user', userId.toString(), data, cacheService.getTTL('default')),
  invalidate: (userId: number) => cacheService.delete('user', userId.toString()),
};

export const healthScoreCache = {
  get: (userId: number) => cacheService.get('healthScore', userId.toString()),
  set: (userId: number, score: any) =>
    cacheService.set('healthScore', userId.toString(), score, cacheService.getTTL('healthScore')),
  invalidate: (userId: number) => cacheService.delete('healthScore', userId.toString()),
};

export const transactionsCache = {
  get: (userId: number, page: number = 1) =>
    cacheService.get('transactions', `${userId}:page:${page}`),
  set: (userId: number, page: number, data: any) =>
    cacheService.set('transactions', `${userId}:page:${page}`, data, cacheService.getTTL('transactions')),
  invalidate: (userId: number) => cacheService.deletePattern(`transactions:${userId}:*`),
};

export const analyticsCache = {
  get: (userId: number, type: string) =>
    cacheService.get('analytics', `${userId}:${type}`),
  set: (userId: number, type: string, data: any) =>
    cacheService.set('analytics', `${userId}:${type}`, data, cacheService.getTTL('analytics')),
  invalidate: (userId: number) => cacheService.deletePattern(`analytics:${userId}:*`),
};

export const mlPredictionCache = {
  get: (userId: number, type: string) =>
    cacheService.get('mlPrediction', `${userId}:${type}`),
  set: (userId: number, type: string, data: any) =>
    cacheService.set('mlPrediction', `${userId}:${type}`, data, cacheService.getTTL('mlPredictions')),
  invalidate: (userId: number) => cacheService.deletePattern(`mlPrediction:${userId}:*`),
};

// Legacy export for backward compatibility
export const cache = {
  set: (key: string, value: any, ttl?: number) => {
    cacheService.set('legacy', key, value, ttl);
  },
  get: (key: string) => {
    return cacheService.get('legacy', key);
  },
  delete: (key: string) => {
    return cacheService.delete('legacy', key);
  }
};

export default cacheService;

import { Pool } from 'pg';
import { config } from './env';
import { logger } from '../utils/logger';

// TODO: Replace with Prisma or TypeORM client
export const db = new Pool({
  connectionString: config.databaseUrl,
  max: 20,
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000,
});

db.on('error', (err) => {
  logger.error(`Unexpected error on idle client: ${err.message}`);
});

// Example query function with better error handling
export const query = async (text: string, params?: any[]) => {
  try {
    const res = await db.query(text, params);
    return res;
  } catch (error: any) {
    logger.error(`Database query error: ${error.message} (Code: ${error.code})`);
    if (error.code === '28P01') {
      logger.error('Database authentication failed. Please check your database credentials in the .env file.');
    }
    throw error;
  }
};

import { Request, Response } from 'express';
import jwt from 'jsonwebtoken';
import { config } from '../config/env';
import { DatabaseService } from '../services/databaseService';

export const verify = async (req: Request, res: Response) => {
  try {
    const authHeader = req.headers.authorization as string | undefined;
    if (!authHeader) return res.status(401).json({ error: 'No token provided' });

    const token = authHeader.split(' ')[1];
    if (!token) return res.status(401).json({ error: 'Invalid token format' });

    const decoded = jwt.verify(token, config.jwtSecret);
    return res.json({ valid: true, payload: decoded });
  } catch (err: any) {
    return res.status(401).json({ valid: false, error: err.message || 'Unauthorized' });
  }
};

export const guestLogin = async (req: Request, res: Response) => {
  try {
    // Generate unique guest ID
    const guestId = `guest_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    const guestEmail = `${guestId}@guest.capstack.local`;
    const guestName = 'Guest User';

    // Create temporary guest user with default PIN
    const userId = await DatabaseService.createGuestUser(guestEmail, guestName);

    if (!userId || userId === 0) {
      return res.status(500).json({ error: 'Failed to create guest session' });
    }

    // Sign token
    const token = jwt.sign(
      { userId, email: guestEmail, name: guestName, isGuest: true },
      config.jwtSecret,
      { expiresIn: '7d' }
    );

    return res.json({
      token,
      user: { id: userId.toString(), email: guestEmail, name: guestName, isGuest: true }
    });
  } catch (error: any) {
    console.error('Guest login error:', error);
    return res.status(500).json({ error: 'Failed to create guest session' });
  }
};

export const login = async (req: Request, res: Response) => {
  try {
    const { email, pin } = req.body;

    if (!email || !pin) {
      return res.status(400).json({ error: 'Email and PIN are required' });
    }

    // Validate PIN is 4 digits
    if (!/^\d{4}$/.test(pin)) {
      return res.status(400).json({ error: 'PIN must be exactly 4 digits' });
    }

    // Get user by email and pin
    const user = await DatabaseService.getUserByEmailAndPin(email, pin);
    if (!user) {
      return res.status(401).json({ error: 'Invalid email or PIN' });
    }

    // Sign token
    const token = jwt.sign(
      { userId: user.id, email: user.email, name: user.name, isGuest: false },
      config.jwtSecret,
      { expiresIn: '7d' }
    );

    return res.json({
      token,
      user: { id: user.id.toString(), email: user.email, name: user.name, isGuest: false }
    });
  } catch (error: any) {
    console.error('Login error:', error);
    return res.status(500).json({ error: 'Login failed. Please try again.' });
  }
};

export const register = async (req: Request, res: Response) => {
  try {
    const { email, pin, name } = req.body;

    if (!email || !pin || !name) {
      return res.status(400).json({ error: 'Email, PIN, and name are required' });
    }

    // Validate PIN is 4 digits
    if (!/^\d{4}$/.test(pin)) {
      return res.status(400).json({ error: 'PIN must be exactly 4 digits' });
    }

    // Check if user already exists
    const existingUser = await DatabaseService.getUserByEmail(email);
    if (existingUser) {
      return res.status(400).json({ error: 'User already exists with this email' });
    }

    // Create new user with PIN
    const userId = await DatabaseService.createUserWithPin(email, name, pin);

    if (!userId || userId === 0) {
      console.error('Failed to create user - userId is 0 or null');
      return res.status(500).json({ error: 'Failed to create user account. Please try again.' });
    }

    const token = jwt.sign(
      { userId, email, name, isGuest: false },
      config.jwtSecret,
      { expiresIn: '7d' }
    );

    return res.json({
      message: 'User registered successfully',
      token,
      user: { id: userId.toString(), email, name, isGuest: false }
    });
  } catch (error: any) {
    console.error('Registration error:', error);
    return res.status(500).json({
      error: 'Registration failed. Please try again.',
      details: error.message
    });
  }
};

import { Request, Response } from 'express';
import { calculateHealthScore } from '../services/healthScoreService';
import { calculateSurvivalMonths } from '../services/survivalService';
import { calculateIncomeSuitabilityScore } from '../services/incomeVarianceService';
import { monteCarloProjection } from '../services/whatIfService';
import { getDebtSnowballRecommendation } from '../services/aiCoachService';
import { logger } from '../utils/logger';

export const calculateFinance = async (req: Request, res: Response) => {
  // TODO: General finance calculations
  const { income, expenses } = req.body;
  const ratio = expenses / income;
  res.json({ expenseRatio: ratio });
};

export const getHealthScore = async (req: Request, res: Response) => {
  const userId = (req as any).userId;
  const isGuest = (req as any).isGuest;

  const startTime = Date.now();
  // For guest users or when no user data is available, use mock data
  const result = await calculateHealthScore(userId || 0);
  const duration = Date.now() - startTime;
  logger.info(`Health score calculation for user ${userId} took ${duration}ms`);

  res.json({
    score: result.totalScore,
    grade: result.grade,
    categoryScores: result.categoryScores,
    insights: result.insights,
    recommendations: result.recommendations,
    isGuest: isGuest || false
  });
};

export const getSurvival = async (req: Request, res: Response) => {
  const userId = (req as any).userId;
  const isGuest = (req as any).isGuest;

  const startTime = Date.now();
  const result = await calculateSurvivalMonths(userId || 0);
  const duration = Date.now() - startTime;
  logger.info(`Survival calculation for user ${userId} took ${duration}ms`);

  res.json({
    months: result.months,
    riskLevel: result.riskLevel,
    breakdown: result.breakdown,
    scenarios: result.scenarios,
    recommendations: result.recommendations,
    isGuest: isGuest || false
  });
};

export const getIncomeScore = async (req: Request, res: Response) => {
  const userId = (req as any).userId;
  const isGuest = (req as any).isGuest;

  const startTime = Date.now();
  const result = await calculateIncomeSuitabilityScore(userId || 0);
  const duration = Date.now() - startTime;
  logger.info(`Income score calculation for user ${userId} took ${duration}ms`);

  res.json({
    score: result.totalScore,
    grade: result.grade,
    riskLevel: result.riskLevel,
    categoryScores: result.categoryScores,
    insights: result.insights,
    recommendations: result.recommendations,
    projections: result.projections,
    isGuest: isGuest || false
  });
};

export const getWhatIfProjection = async (req: Request, res: Response) => {
  const userId = 1; // Use demo user ID 1 for all requests
  const { jobLoss, raise, expenseChange } = req.body;

  const startTime = Date.now();
  const result = await monteCarloProjection(userId, jobLoss, raise, expenseChange);
  const duration = Date.now() - startTime;
  logger.info(`What-if projection for user ${userId} took ${duration}ms`);

  if (!result) {
    // Fallback response for demo
    const demoResult = {
      projection: [
        { year: 1, netWorth: 200000, upperBound: 220000, lowerBound: 180000 },
        { year: 2, netWorth: 230000, upperBound: 260000, lowerBound: 200000 },
        { year: 3, netWorth: 265000, upperBound: 310000, lowerBound: 220000 },
        { year: 4, netWorth: 305000, upperBound: 370000, lowerBound: 240000 },
        { year: 5, netWorth: 350000, upperBound: 440000, lowerBound: 260000 },
        { year: 6, netWorth: 400000, upperBound: 520000, lowerBound: 280000 },
        { year: 7, netWorth: 460000, upperBound: 610000, lowerBound: 310000 },
        { year: 8, netWorth: 525000, upperBound: 720000, lowerBound: 330000 },
        { year: 9, netWorth: 600000, upperBound: 850000, lowerBound: 350000 },
        { year: 10, netWorth: 685000, upperBound: 1000000, lowerBound: 370000 }
      ]
    };
    return res.json(demoResult);
  }

